-- The two checklists published on 2026-11-24: When Someone's Memory Is Going
-- (Memory Loss) and Going to a Party Without Drinking (Sober Socializing).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-24`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-someones-memory-is-going', 'When Someone''s Memory Is Going', 'Open this when a person you love is forgetting things that matter, and every visit asks something new of you. It offers ways to make the time together easier for both of you, and room for the grief that comes with it.', 'Memory Loss', '["Go with what they said, not the facts — Correcting a wrong year wins nothing and costs the mood.", "Ask one thing at a time — Two questions in one sentence is two too many.", "Bring something to do with your hands — Folding or sorting together beats hunting for conversation.", "Put the same things in the same places — A predictable room does some of the remembering for them.", "Write what you did on a shared note — A line by the door tells the next visitor where to pick up.", "Let the same story be new again — They are not repeating it at you, they are telling it to you.", "Say the goodbye warmly and briefly — A long leaving is harder on both of you than a short one.", "Grieve the person while they are here — Missing who they were is not disloyal, and it needs somewhere to go."]'::jsonb, 'weekly', array['Caregiving', 'Family', 'Resilience']::text[], 1, '2026-11-24T16:00:00+00:00'::timestamptz),
  ('going-to-a-party-without-drinking', 'Going to a Party Without Drinking', 'Open this before an evening where everyone else will be drinking and you are not, whether that is new for you or long settled. It gives you a drink to hold, an answer to the question, and a way out when you have had enough.', 'Sober Socializing', '["Get a drink in your hand on arrival — A full glass stops the offers before they start.", "Decide your one-line answer in advance — A short, settled reply needs no footnote and ends the subject.", "Eat before you go — Arriving hungry makes every decision of the evening harder.", "Find the one person you can be honest with — Having an ally in the room changes the whole evening.", "Give yourself a leaving time — Knowing when you go makes staying easier.", "Book the ride home before you need it — A ride already arranged removes the excuse for staying too long.", "Have something to do after the speeches — The lull once the formal part ends is the hardest stretch.", "Leave without announcing it — A quiet exit saves you ten conversations about leaving."]'::jsonb, 'as needed', array['Boundaries', 'Social Anxiety', 'Resilience']::text[], 1, '2026-11-24T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
